xpath_ast_node* parse_filter_expression()
{
	xpath_ast_node* n = parse_primary_expression();
	if (!n) return 0;

	while (_lexer.current() == lex_open_square_brace)
	{
		_lexer.next();

		if (n->rettype() != xpath_type_node_set)
			return error("Predicate has to be applied to node set");

		xpath_ast_node* expr = parse_expression();
		if (!expr) return 0;

		n = alloc_node(ast_filter, n, expr, predicate_default);
		if (!n) return 0;

		if (_lexer.current() != lex_close_square_brace)
			return error("Expected ']' to match an opening '['");

		_lexer.next();
	}

	return n;
}

xpath_ast_node* parse_filter_expression()
{
	xpath_ast_node* n = parse_primary_expression();
	if (!n) return 0;

	size_t old_depth = _depth;

	while (_lexer.current() == lex_open_square_brace)
	{
		_lexer.next();

		if (++_depth > xpath_ast_depth_limit)
			return error_rec();

		if (n->rettype() != xpath_type_node_set)
			return error("Predicate has to be applied to node set");

		xpath_ast_node* expr = parse_expression();
		if (!expr) return 0;

		n = alloc_node(ast_filter, n, expr, predicate_default);
		if (!n) return 0;

		if (_lexer.current() != lex_close_square_brace)
			return error("Expected ']' to match an opening '['");

		_lexer.next();
	}

	_depth = old_depth;

	return n;
}

xpath_ast_node* parse_step(xpath_ast_node* set)
{
	if (set && set->rettype() != xpath_type_node_set)
		return error("Step has to be applied to node set");

	bool axis_specified = false;
	axis_t axis = axis_child; // implied child axis

	if (_lexer.current() == lex_axis_attribute)
	{
		axis = axis_attribute;
		axis_specified = true;

		_lexer.next();
	}
	else if (_lexer.current() == lex_dot)
	{
		_lexer.next();

		if (_lexer.current() == lex_open_square_brace)
			return error("Predicates are not allowed after an abbreviated step");

		return alloc_node(ast_step, set, axis_self, nodetest_type_node, 0);
	}
	else if (_lexer.current() == lex_double_dot)
	{
		_lexer.next();

		if (_lexer.current() == lex_open_square_brace)
			return error("Predicates are not allowed after an abbreviated step");

		return alloc_node(ast_step, set, axis_parent, nodetest_type_node, 0);
	}

	nodetest_t nt_type = nodetest_none;
	xpath_lexer_string nt_name;

	if (_lexer.current() == lex_string)
	{
		// node name test
		nt_name = _lexer.contents();
		_lexer.next();

		// was it an axis name?
		if (_lexer.current() == lex_double_colon)
		{
			// parse axis name
			if (axis_specified)
				return error("Two axis specifiers in one step");

			axis = parse_axis_name(nt_name, axis_specified);

			if (!axis_specified)
				return error("Unknown axis");

			// read actual node test
			_lexer.next();

			if (_lexer.current() == lex_multiply)
			{
				nt_type = nodetest_all;
				nt_name = xpath_lexer_string();
				_lexer.next();
			}
			else if (_lexer.current() == lex_string)
			{
				nt_name = _lexer.contents();
				_lexer.next();
			}
			else
			{
				return error("Unrecognized node test");
			}
		}

		if (nt_type == nodetest_none)
		{
			// node type test or processing-instruction
			if (_lexer.current() == lex_open_brace)
			{
				_lexer.next();

				if (_lexer.current() == lex_close_brace)
				{
					_lexer.next();

					nt_type = parse_node_test_type(nt_name);

					if (nt_type == nodetest_none)
						return error("Unrecognized node type");

					nt_name = xpath_lexer_string();
				}
				else if (nt_name == PUGIXML_TEXT("processing-instruction"))
				{
					if (_lexer.current() != lex_quoted_string)
						return error("Only literals are allowed as arguments to processing-instruction()");

					nt_type = nodetest_pi;
					nt_name = _lexer.contents();
					_lexer.next();

					if (_lexer.current() != lex_close_brace)
						return error("Unmatched brace near processing-instruction()");
					_lexer.next();
				}
				else
				{
					return error("Unmatched brace near node type test");
				}
			}
			// QName or NCName:*
			else
			{
				if (nt_name.end - nt_name.begin > 2 && nt_name.end[-2] == ':' && nt_name.end[-1] == '*') // NCName:*
				{
					nt_name.end--; // erase *

					nt_type = nodetest_all_in_namespace;
				}
				else
				{
					nt_type = nodetest_name;
				}
			}
		}
	}
	else if (_lexer.current() == lex_multiply)
	{
		nt_type = nodetest_all;
		_lexer.next();
	}
	else
	{
		return error("Unrecognized node test");
	}

	const char_t* nt_name_copy = alloc_string(nt_name);
	if (!nt_name_copy) return 0;

	xpath_ast_node* n = alloc_node(ast_step, set, axis, nt_type, nt_name_copy);
	if (!n) return 0;

	xpath_ast_node* last = 0;

	while (_lexer.current() == lex_open_square_brace)
	{
		_lexer.next();

		xpath_ast_node* expr = parse_expression();
		if (!expr) return 0;

		xpath_ast_node* pred = alloc_node(ast_predicate, 0, expr, predicate_default);
		if (!pred) return 0;

		if (_lexer.current() != lex_close_square_brace)
			return error("Expected ']' to match an opening '['");
		_lexer.next();

		if (last) last->set_next(pred);
		else n->set_right(pred);

		last = pred;
	}

	return n;
}

